<?php
// phpr compatibility layer: lets event code written for phpr run unchanged
// (DB::Query, Security::getUserName, $pageObject, $xt, $record, runner_mail...).
// Classes live in the global namespace, like in phpr.

namespace MiB {

    /** Helpers used by the event wrappers generated by the phpr importer. */
    class Compat
    {
        public static function page($type, $table)
        {
            return new \CompatPage((string)$type, (string)$table);
        }

        public static function xt()
        {
            static $xt = null;
            if ($xt === null) $xt = new \CompatXt();
            return $xt;
        }

        /** Key values of a record of $table. */
        public static function keys($table, $row)
        {
            if (!$table || !App::$i->hasTable($table) || !is_array($row)) return [];
            return App::$i->table($table)->keysFromRow($row);
        }

        /** SQL WHERE for the given keys, like the classic $where. */
        public static function where($table, $keys)
        {
            if (!$keys) return '1=0';
            $db = $table && App::$i->hasTable($table) ? App::$i->table($table)->db : App::$i->db();
            $parts = [];
            foreach ($keys as $k => $v) $parts[] = $db->q($k) . '=' . ($v === null ? 'NULL' : $db->pdo->quote((string)$v));
            return implode(' AND ', $parts);
        }

        /**
         * BeforeMoveNext: $record["<field>_value"] replaces the cell HTML, $record["<field>_css"]
         * and $record["css"] add inline styles to the cell / the row.
         */
        public static function applyRecord($table, array &$data, array $record)
        {
            if (!$record) return;
            $t = App::$i->table($table);
            foreach ($t->def['fields'] as $f) {
                $good = self::goodName($f['name']);
                foreach ([$good, $f['name']] as $k) {
                    if (isset($record[$k . '_value'])) $data['__html'][$f['name']] = (string)$record[$k . '_value'];
                    if (isset($record[$k . '_css'])) $data['__css'][$f['name']] = (string)$record[$k . '_css'];
                }
            }
            if (isset($record['css'])) $data['__rowcss'] = (string)$record['css'];
            if (isset($record['rowcss'])) $data['__rowcss'] = (string)$record['rowcss'];
        }

        public static function goodName($name)
        {
            return preg_replace('/[^A-Za-z0-9_]/', '_', $name);
        }
    }
}

namespace {

    if (!function_exists('now')) {
        function now() { return date('Y-m-d H:i:s'); }
    }

    /** Statement wrapper returned by DB::Query. */
    class CompatResult
    {
        private $st;
        public function __construct($st) { $this->st = $st; }
        public function fetchAssoc()
        {
            $r = $this->st->fetch(\PDO::FETCH_ASSOC);
            if (!$r) return false;
            foreach ($r as $k => $v) if (is_resource($v)) $r[$k] = stream_get_contents($v);
            return $r;
        }
        public function fetchNumeric()
        {
            $r = $this->st->fetch(\PDO::FETCH_NUM);
            return $r ?: false;
        }
        public function value($i)
        {
            $r = $this->st->fetch(\PDO::FETCH_BOTH);
            return $r && isset($r[$i]) ? $r[$i] : null;
        }
        public function getData() { return $this->st->fetchAll(\PDO::FETCH_ASSOC); }
        public function fetchAll() { return $this->getData(); }
        public function numRows() { return $this->st->rowCount(); }
    }

    /** Connection object returned by DB::CurrentConnection() / DB::ConnectionByID(). */
    class CompatConnection
    {
        /** @var \MiB\Db */
        public $db;
        public function __construct(\MiB\Db $db) { $this->db = $db; }
        public function query($sql) { return new CompatResult($this->db->pdo->query($sql)); }
        public function exec($sql) { return $this->db->pdo->exec($sql) !== false; }
        public function execSilent($sql) { try { return $this->exec($sql); } catch (\Throwable $e) { return false; } }
        public function querySilent($sql) { try { return $this->query($sql); } catch (\Throwable $e) { return false; } }
        public function addFieldWrappers($name) { return $this->db->q($name); }
        public function addTableWrappers($name) { return $this->db->table($name); }
        public function prepareString($s) { return $this->db->pdo->quote((string)$s); }
        public function escapeString($s) { return substr($this->db->pdo->quote((string)$s), 1, -1); }
        public function getInsertedId() { return $this->db->pdo->lastInsertId(); }
        public function lastError() { $e = $this->db->pdo->errorInfo(); return isset($e[2]) ? $e[2] : ''; }
        public function dbType() { return $this->db->driver; }
    }

    /** the classic database API. */
    class DB
    {
        private static $current = null;

        /** @return \MiB\Db */
        private static function conn()
        {
            return \MiB\App::$i->db(self::$current);
        }

        public static function SetConnection($id) { self::$current = $id === '' ? null : $id; }
        public static function CurrentConnection() { return new CompatConnection(self::conn()); }
        public static function DefaultConnection() { return new CompatConnection(\MiB\App::$i->db()); }
        public static function ConnectionByID($id) { return new CompatConnection(\MiB\App::$i->db($id)); }
        public static function Query($sql) { return new CompatResult(self::conn()->pdo->query($sql)); }
        public static function Exec($sql) { return self::conn()->pdo->exec($sql) !== false; }
        public static function LastId() { return self::conn()->pdo->lastInsertId(); }
        public static function LastError() { $e = self::conn()->pdo->errorInfo(); return isset($e[2]) ? $e[2] : ''; }

        public static function DBLookup($sql)
        {
            $v = self::conn()->pdo->query($sql)->fetchColumn();
            return $v === false ? null : $v;
        }

        public static function Lookup($sql) { return self::DBLookup($sql); }

        private static function whereSql($where)
        {
            if (is_array($where)) {
                list($w, $p) = self::conn()->where($where);
                foreach ($p as $v) $w = preg_replace('/\?/', self::conn()->pdo->quote((string)$v), $w, 1);
                return $w;
            }
            return (string)$where === '' ? '1=1' : (string)$where;
        }

        public static function Select($table, $where = '')
        {
            return new CompatResult(self::conn()->pdo->query('SELECT * FROM ' . self::conn()->table($table) . ' WHERE ' . self::whereSql($where)));
        }

        public static function Insert($table, $data)
        {
            self::conn()->insert($table, $data);
            return true;
        }

        public static function Update($table, $data, $where)
        {
            if (is_array($where)) return self::conn()->update($table, $data, $where) >= 0;
            $set = [];
            $params = [];
            foreach ($data as $k => $v) { $set[] = self::conn()->q($k) . ' = ?'; $params[] = $v; }
            self::conn()->query('UPDATE ' . self::conn()->table($table) . ' SET ' . implode(', ', $set) . ' WHERE ' . self::whereSql($where), $params);
            return true;
        }

        public static function Delete($table, $where)
        {
            self::conn()->pdo->exec('DELETE FROM ' . self::conn()->table($table) . ' WHERE ' . self::whereSql($where));
            return true;
        }

        /** DB::PrepareSQL("select * from t where id=:1 and user=':user.username'", $id) */
        public static function PrepareSQL($sql)
        {
            $args = array_slice(func_get_args(), 1);
            $pdo = self::conn()->pdo;
            $sql = preg_replace_callback("/':?(\\d+)'|:(\\d+)/", function ($m) use ($args, $pdo) {
                $i = (int)($m[1] !== '' ? $m[1] : $m[2]) - 1;
                $v = isset($args[$i]) ? $args[$i] : null;
                if ($m[1] !== '') return $pdo->quote((string)$v);
                return is_numeric($v) ? (string)$v : $pdo->quote((string)$v);
            }, $sql);
            return preg_replace_callback("/':?user\\.(\\w+)'|:user\\.(\\w+)/", function ($m) use ($pdo) {
                $k = $m[1] !== '' ? $m[1] : $m[2];
                $u = user() ?: [];
                $v = $k === 'username' ? userName() : (isset($u[$k]) ? $u[$k] : '');
                return $pdo->quote((string)$v);
            }, $sql);
        }
    }

    /** the classic Security API (read-only parts). */
    class Security
    {
        public static function getUserName() { return (string)userName(); }
        public static function getDisplayName() { $u = user(); return $u ? ($u['fullname'] ?: $u['username']) : ''; }
        public static function getUserGroup() { $g = userGroups(); return $g ? $g[0] : ''; }
        public static function getUserGroups() { return array_fill_keys(userGroups(), true); }
        public static function isAdmin() { return isAdmin(); }
        public static function isLoggedIn() { return (bool)user(); }
        public static function isGuest() { return !user(); }
        public static function getUserData() { return user() ?: []; }
        public static function getPermissions($table) { $s = ''; foreach (str_split(\MiB\Security::ALL) as $l) if (\MiB\App::$i->security->can($table, $l)) $s .= $l; return $s; }
        public static function logout() { \MiB\App::$i->security->logout(); }
    }

    /** $pageObject stand-in: known properties, every other method is a no-op. */
    class CompatPage
    {
        public $pageType;
        public $tName;
        public $id = 1;
        public $mode = 0;
        public function __construct($type, $table) { $this->pageType = $type; $this->tName = $table; }
        public function getMasterRecord()
        {
            if (empty($_GET['mt']) || !\MiB\App::$i->hasTable((string)$_GET['mt'])) return null;
            $m = \MiB\App::$i->table((string)$_GET['mt']);
            try { return $m->fetchOne($m->keysFromRequest(['k' => isset($_GET['mk']) ? $_GET['mk'] : []])); } catch (\Throwable $e) { return null; }
        }
        public function getCurrentRecord() { return null; }
        public function setMessage($msg) { \MiB\App::$i->flash('info', strip_tags((string)$msg)); }
        public function __call($name, $args) { return null; }
        public function __get($name) { return null; }
    }

    /** $xt (template engine) stand-in. */
    class CompatXt
    {
        public $vars = [];
        public function assign($name, $value) { $this->vars[$name] = $value; }
        public function __call($name, $args) { return null; }
    }

    function runner_mail($params)
    {
        $body = isset($params['htmlbody']) ? $params['htmlbody'] : (isset($params['body']) ? nl2br(h($params['body'])) : '');
        $ok = sendMail(isset($params['to']) ? $params['to'] : '', isset($params['subject']) ? $params['subject'] : '', $body, true);
        return ['mailed' => (bool)$ok, 'message' => $ok ? '' : 'mail error'];
    }

    if (!function_exists('my_json_encode')) { function my_json_encode($v) { return json_encode($v); } }
    if (!function_exists('runner_htmlspecialchars')) { function runner_htmlspecialchars($s) { return h($s); } }
    if (!function_exists('isLoggedAsGuest')) { function isLoggedAsGuest() { return !user(); } }
    if (!function_exists('GetFullSiteUrl')) {
        function GetFullSiteUrl() { $https = !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off'; return ($https ? 'https' : 'http') . '://' . $_SERVER['HTTP_HOST'] . rtrim(dirname($_SERVER['SCRIPT_NAME']), '/'); }
    }
    if (!function_exists('GetTableLink')) {
        function GetTableLink($table, $page = 'list', $params = '') { return 'index.php?p=' . ($page === '' ? 'list' : $page) . '&t=' . rawurlencode($table) . ($params !== '' ? '&' . $params : ''); }
    }
}
